import{_ as a,o as t,c as o,a0 as r}from"./chunks/framework.ZP6uZ4uc.js";const u=JSON.parse('{"title":"Capstone 概览","description":"","frontmatter":{},"headers":[],"relativePath":"phase5-research/week10/capstone-overview.md","filePath":"phase5-research/week10/capstone-overview.md","lastUpdated":null}'),s={name:"phase5-research/week10/capstone-overview.md"};function i(n,e,l,h,p,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="capstone-概览" tabindex="-1">Capstone 概览 <a class="header-anchor" href="#capstone-概览" aria-label="Permalink to &quot;Capstone 概览&quot;">​</a></h1><h2 id="科研问题链" tabindex="-1">科研问题链 <a class="header-anchor" href="#科研问题链" aria-label="Permalink to &quot;科研问题链&quot;">​</a></h2><p>按照 <strong>Question → Hypothesis → Method → Experiment → Conclusion</strong> 的结构组织项目。</p><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h3><p><strong>Question:</strong> 在需求不确定时，预测信息能否改善共享单车重分配决策？</p><p><strong>Hypothesis:</strong> 更可靠的需求预测通常能降低运营成本，但预测指标更优不必然意味着决策质量更高。</p><p><strong>Method:</strong> 用相同优化模型分别接入历史平均预测、机器学习预测和真实未来需求。</p><p><strong>Experiment:</strong> 在统一测试期内比较预测误差、运输成本、未满足需求、总成本与 regret。</p><p><strong>Conclusion:</strong> 说明何种信息带来价值、何种误差最关键。</p><hr><h2 id="项目目标" tabindex="-1">项目目标 <a class="header-anchor" href="#项目目标" aria-label="Permalink to &quot;项目目标&quot;">​</a></h2><ol><li>完成端到端的&quot;预测 + 优化&quot;流程</li><li>理解预测误差如何影响决策</li><li>学会设计公平的实验比较</li><li>表达假设与局限</li></ol><hr><h2 id="最终成果" tabindex="-1">最终成果 <a class="header-anchor" href="#最终成果" aria-label="Permalink to &quot;最终成果&quot;">​</a></h2><ul><li>一个整洁的 GitHub repository</li><li>一个能够从头运行的主 Notebook</li><li>一份 3-5 页小报告</li><li>README 说明问题、数据、方法、结果</li></ul><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>👉 <a href="./data-layer">数据层</a></p>',18)])])}const _=a(s,[["render",i]]);export{u as __pageData,_ as default};
